const go = (id, label, text, next, effects = {}) => ({
  id, label, intent: 'choose', automatic: true,
  outcomes: { success: { text, next, ...effects } },
});
const check = (id, label, stat, dc, risk, next, texts, effects = {}) => ({
  id, label, intent: 'investigate', stat, dc, risk,
  outcomes: Object.fromEntries(['critical', 'success', 'failure', 'fumble'].map((grade, i) => [grade, {
    text: texts[i], next,
    ...(grade === 'critical' ? { pressure: -1 } : grade === 'failure' ? { pressure: 1 } : grade === 'fumble' ? { pressure: 2 } : {}),
    ...(effects[grade] || {}),
  }])),
});
const use = (id, label, item, text, next, effects = {}, consume = false) => ({
  ...go(id, label, text, next, effects),
  requires: { item }, [consume ? 'consumeItems' : 'useItems']: [item],
  lockedHint: '앞선 장면에서 이 물건을 챙겨 아직 가지고 있어야 한다.',
});
